program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    known = {}
    for c in range(w):
        vals = [grid[r][c] for r in range(c + 1, h) if c < w and grid[r][c] != 0]
        if vals:
            known[c] = max(set(vals), key=vals.count)
    period = None
    for p in range(1, w + 1):
        groups = {}
        ok = True
        for c, v in known.items():
            k = c % p
            if k in groups and groups[k] != v:
                ok = False
                break
            groups[k] = v
        if ok and len(groups) >= min(p, 6):
            period = p
            break
    if period is None:
        period = w
    seq = [None] * period
    for c, v in known.items():
        k = c % period
        if seq[k] is None:
            seq[k] = v
    # Remaining cycle entries are read from the most reliable observed sequence;
    # ordinary task grids provide at least one lower-triangle sample per phase.
    for k in range(period):
        if seq[k] is None:
            seq[k] = next((v for c, v in known.items() if c % period == k), 0)
    return [[seq[(c - 1) % period] if c >= r else seq[c % period]
             for c in range(w)] for r in range(h)]
'''
